const commandSchema = {
  "type": "object",
  "properties": {
    "command": {
      "type": "string",
      "enum": ["CreateShape", "CreateTextBox"],
      "description": "The command type to execute."
    },
    "parameters": {
      "type": "object",
      "properties": {
        "shapes": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "shape_id": {
                "type": "string",
                "description": "Unique identifier for the shape."
              },
              "shape_type": {
                "type": "string",
                "description": "Type of shape (e.g., 'Square', 'Circle', 'TextBox')."
              },
              "shape_color": {
                "type": "string",
                "description": "Color of the shape in hex format (e.g., '#FF0000')."
              },
              "text": {
                "type": "string",
                "description": "Text content of the shape."
              },
              "pos_x": {
                "type": "number",
                "description": "X-coordinate position as percentage of page width."
              },
              "pos_y": {
                "type": "number",
                "description": "Y-coordinate position as percentage of page height."
              },
              "width": {
                "type": "number",
                "description": "Width as percentage of page width."
              },
              "height": {
                "type": "number",
                "description": "Height as percentage of page height."
              },
              "angle": {
                "type": "number",
                "description": "Rotation angle in degrees."
              },
              "z_order": {
                "type": "integer",
                "description": "Z-index for shape layering."
              },
              "custom_properties": {
                "type": "object",
                "description": "Custom key-value properties for the shape."
              },
              "is_connector": {
                "type": "boolean",
                "description": "Whether the shape is a connector."
              },
              "connector_type": {
                "type": "string",
                "description": "Type of connector if is_connector is true."
              },
              "source_shape_id": {
                "type": "string",
                "description": "ID of shape where connector begins."
              },
              "target_shape_id": {
                "type": "string",
                "description": "ID of shape where connector ends."
              },
              "begin_x": {
                "type": "number",
                "description": "X-coordinate of connector start point."
              },
              "begin_y": {
                "type": "number",
                "description": "Y-coordinate of connector start point."
              },
              "end_x": {
                "type": "number",
                "description": "X-coordinate of connector end point."
              },
              "end_y": {
                "type": "number",
                "description": "Y-coordinate of connector end point."
              },
              "routing_points": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "x": {
                      "type": "number"
                    },
                    "y": {
                      "type": "number"
                    }
                  }
                }
              },
              "connector_pattern": {
                "type": "string",
                "description": "Pattern style for connector lines."
              },
              "connector_weight": {
                "type": "number",
                "description": "Line weight/thickness for connectors."
              },
              "connector_rounding": {
                "type": "string",
                "description": "Rounding style for connector corners."
              }
            }
          }
        }
      }
    }
  },
  "required": ["command", "parameters"]
};

return {
  schema: JSON.stringify(commandSchema)
};

// Get the input object
const input = $input.first();

// Parse the raw JSON string
let rawJson = input.json.output.trim();

// Step 1: Remove unwanted characters and fix formatting
rawJson = rawJson
    .replace(/```[a-z]*\n?/g, '') // Remove Markdown-like formatting (e.g., ```json)
    .replace(/\\n/g, '') // Remove escaped newlines
    .replace(/\\"/g, '"') // Fix escaped quotes
    .replace(/,\s*}/g, '}') // Remove trailing commas before closing braces
    .replace(/,\s*]/g, ']'); // Remove trailing commas before closing arrays

// Step 2: Ensure the JSON starts and ends with proper braces
if (!rawJson.startsWith('{')) {
    rawJson = '{' + rawJson; // Add missing opening brace
}
if (!rawJson.endsWith('}')) {
    rawJson = rawJson + '}'; // Add missing closing brace
}

// Step 3: Attempt to parse the cleaned JSON string
let parsedJson;
try {
    parsedJson = JSON.parse(rawJson); // Parse the cleaned JSON
} catch (error) {
    throw new Error('Failed to parse JSON: ' + error.message + '\nProblematic JSON:\n' + rawJson);
}

// Return the cleaned JSON object
return parsedJson;
